ame":"reviewed_at","type":"timestamp with time zone","required":false,"pk":false,"unique":false,"reference":null}]},{"table":"user_access_assignment","columns":[{"name":"access_assignment_id","type":"integer","required":true,"pk":true,"unique":false,"reference":null},{"name":"clerk_user_id","type":"character varying(255)","required":true,"pk":false,"unique":true,"reference":null},{"name":"app_role","type":"character varying(30)","required":true,"pk":false,"unique":false,"reference":null},{"name":"access_status","type":"character varying(20)","required":true,"pk":false,"unique":false,"reference":null},{"name":"created_at","type":"timestamp with time zone","required":true,"pk":false,"unique":false,"reference":null},{"name":"updated_at","type":"timestamp with time zone","required":true,"pk":false,"unique":false,"reference":null}]},{"table":"user_access_audit_log","columns":[{"name":"access_audit_id","type":"integer","required":true,"pk":true,"unique":false,"reference":null},{"name":"access_assignment_id","type":"integer","required":true,"pk":false,"unique":false,"reference":["user_access_assignment","access_assignment_id"]},{"name":"performed_by_clerk_user_id","type":"character varying(255)","required":true,"pk":false,"unique":false,"reference":null},{"name":"change_type","type":"character varying(30)","required":true,"pk":false,"unique":false,"reference":null},{"name":"old_value","type":"character varying(50)","required":false,"pk":false,"unique":false,"reference":null},{"name":"new_value","type":"character varying(50)","required":true,"pk":false,"unique":false,"reference":null},{"name":"reason","type":"text","required":false,"pk":false,"unique":false,"reference":null},{"name":"created_at","type":"timestamp with time zone","required":true,"pk":false,"unique":false,"reference":null}]},{"table":"forecast_decision_audit_log","columns":[{"name":"decision_audit_id","type":"integer","required":true,"pk":true,"unique":false,"reference":null},{"name":"proposed_section_id","type":"integer","required":true,"pk":false,"unique":false,"reference":["proposed_class_section","proposed_section_id"]},{"name":"action_type","type":"character varying(30)","required":true,"pk":false,"unique":false,"reference":null},{"name":"old_status","type":"character varying(30)","required":false,"pk":false,"unique":false,"reference":null},{"name":"new_status","type":"character varying(30)","required":true,"pk":false,"unique":false,"reference":null},{"name":"reason","type":"text","required":false,"pk":false,"unique":false,"reference":null},{"name":"recorded_by","type":"character varying(255)","required":true,"pk":false,"unique":false,"reference":null},{"name":"recorded_at","type":"timestamp with time zone","required":true,"pk":false,"unique":false,"reference":null}]}]'::jsonb;
 t jsonb; c jsonb; actual record; actual_count integer;
BEGIN
SELECT count(*) INTO actual_count FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='public' AND r.relkind IN ('r','p');
IF actual_count<>26 THEN RAISE EXCEPTION 'Expected 26 domain tables, found %',actual_count; END IF;

FOR t IN SELECT * FROM jsonb_array_elements(expected) LOOP
 IF to_regclass('public.'||(t->>'table')) IS NULL THEN RAISE EXCEPTION 'Missing table %',t->>'table'; END IF;
 SELECT count(*) INTO actual_count FROM information_schema.columns WHERE table_schema='public' AND table_name=t->>'table';
 IF actual_count<>jsonb_array_length(t->'columns') THEN RAISE EXCEPTION 'Unexpected columns in %',t->>'table'; END IF;
 FOR c IN SELECT * FROM jsonb_array_elements(t->'columns') LOOP
   SELECT a.attnum,a.attnotnull,format_type(a.atttypid,a.atttypmod) AS type,a.attidentity
     INTO actual FROM pg_attribute a WHERE a.attrelid=to_regclass('public.'||(t->>'table')) AND a.attname=c->>'name' AND NOT a.attisdropped;
   IF NOT FOUND OR actual.type<>c->>'type' OR actual.attnotnull<>(c->>'required')::boolean THEN
     RAISE EXCEPTION 'Column mapping mismatch %.%',t->>'table',c->>'name';
   END IF;
   IF (c->>'pk')::boolean AND (actual.attidentity='' OR NOT EXISTS(
     SELECT 1 FROM pg_constraint k WHERE k.conrelid=to_regclass('public.'||(t->>'table')) AND k.contype='p' AND k.conkey=ARRAY[actual.attnum]::smallint[])) THEN RAISE EXCEPTION 'PK/identity mismatch'; END IF;
   IF (c->>'unique')::boolean AND NOT EXISTS(
     SELECT 1 FROM pg_constraint k WHERE k.conrelid=to_regclass('public.'||(t->>'table')) AND k.contype='u' AND k.conkey=ARRAY[actual.attnum]::smallint[]) THEN RAISE EXCEPTION 'Missing source unique'; END IF;
   IF c->'reference'<>'null'::jsonb AND NOT EXISTS(
     SELECT 1 FROM pg_constraint k JOIN pg_attribute a ON a.attrelid=k.confrelid AND a.attnum=k.confkey[1]
     WHERE k.conrelid=to_regclass('public.'||(t->>'table')) AND k.contype='f' AND k.conkey=ARRAY[actual.attnum]::smallint[]
       AND k.confrelid=to_regclass('public.'||(c->'reference'->>0)) AND a.attname=c->'reference'->>1) THEN RAISE EXCEPTION 'FK mapping mismatch'; END IF;
 END LOOP;
END LOOP;
SELECT count(*) INTO actual_count FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='public' AND c.contype='f';
IF actual_count<>39 THEN RAISE EXCEPTION 'Expected exactly 39 source FKs'; END IF;
END $verify$;
