DO $v$ BEGIN IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('s',c.relowner))) a WHERE n.nspname='public' AND c.relkind='S' AND a.grantee=0) THEN RAISE EXCEPTION 'PUBLIC has identity sequence privileges'; END IF; END $v$;
DO $v$ BEGIN IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='public' AND left(p.proname,3)='db_' AND a.grantee=0) THEN RAISE EXCEPTION 'PUBLIC can execute internal integrity functions'; END IF; END $v$;
